import json

# Check all sessions for errors
import glob
traj_files = sorted(glob.glob("/home/node/.openclaw/agents/main/sessions/*.trajectory.jsonl"), reverse=True)

for tf in traj_files[:20]:
    fname = tf.split('/')[-1]
    errors = []
    with open(tf) as fh:
        for line in fh:
            try:
                entry = json.loads(line)
                msg = entry.get('message', {})
                if msg.get('stopReason') == 'error':
                    errors.append((msg.get('provider','?'), msg.get('model','?'), msg.get('errorMessage','?')))
                ct = entry.get('customType','')
                if ct and 'error' in ct.lower():
                    data = entry.get('data', {})
                    errors.append(('CUSTOM', ct, json.dumps(data)[:150]))
                # Also check for "terminated" in error messages
                err_msg = msg.get('errorMessage','')
                if 'terminated' in err_msg or 'timed out' in err_msg:
                    errors.append((msg.get('provider','?'), msg.get('model','?'), err_msg[:150]))
            except:
                pass
    if errors:
        print(f"\n=== {fname} ({len(errors)} errors) ===")
        for p, m, e in errors[:5]:
            print(f"  {p}/{m}: {e[:200]}")
