import json, glob, re

# Look at actual session files for errors - especially the most recent ones that have user messages
# Check trajectory files for error patterns
for f in sorted(glob.glob("/home/node/.openclaw/agents/main/sessions/*.trajectory.jsonl"), reverse=True)[:5]:
    fname = f.split('/')[-1]
    with open(f) as fh:
        content = fh.read()

    error_patterns = ['terminated', 'timed out', 'Something went wrong', 'stopReason": "error"']
    matches = []
    for pat in error_patterns:
        for m in re.finditer(pat, content):
            # Get context around the match
            start = max(0, m.start() - 50)
            end = min(len(content), m.end() + 100)
            matches.append(content[start:end])

    if matches:
        print(f"\n=== {fname} ===")
        for m in matches[:3]:
            print(f"  ...{m}...")
    else:
        print(f"\n=== {fname} === (no error patterns)")
PYEOF

