python3 << 'PYEOF'
import json, glob, re

# Check actual session .jsonl files for errors
for f in sorted(glob.glob("/home/node/.openclaw/agents/main/sessions/*.jsonl"), reverse=True)[:8]:
    if f.endswith('trajectory.jsonl') or f.endswith('sessions.json'):
        continue
    fname = f.split('/')[-1]
    content = open(f).read()

    # Look for user messages and error patterns
    error_lines = []
    user_msgs = 0
    for line in content.split('\n'):
        if not line.strip():
            continue
        try:
            entry = json.loads(line)
        except:
            continue

        msg = entry.get('message', {})
        if msg.get('role') == 'user':
            user_msgs += 1

        # Check for error or something went wrong
        text_content = json.dumps(entry)
        if 'Something went wrong' in text_content or 'terminated' in text_content or 'timed out' in text_content or 'errorMessage' in text_content:
            error_lines.append(text_content[:300])

    if error_lines:
        print(f"\n=== {fname} (user_msgs={user_msgs}, errors={len(error_lines)}) ===")
        for el in error_lines[:5]:
            print(f"  {el[:250]}")
    else:
        print(f"\n=== {fname} (user_msgs={user_msgs}) === (no errors)")
PYEOF

